  const sidebarRef = useRef<HTMLElement>(null);
  useEffect(() => { if (mobileNav && isMobile) sidebarRef.current?.querySelector<HTMLAnchorElement>("a")?.focus(); }, [mobileNav, isMobile]);
  const runLock = useRef(false); const currentSite = useRef(siteId); const initialLoad = useRef(false); const [clock] = useState(() => Date.now());
  const chooseSite = useCallback((id: string) => { if (currentSite.current === id) return; currentSite.current = id; setSiteId(id); setState(null); setDetail(null); setDocument(null); setRunSetup(false); setForm(null); setEditItem(null); setPreferredPromptId(undefined); setLoading(Boolean(id)); setError(""); setModel("all"); }, []);
  const flash = useCallback((message: string) => setToast(message), []);
  useEffect(() => { if (!toast) return; const timer = setTimeout(() => setToast(""), 4000); return () => clearTimeout(timer); }, [toast]);
  useEffect(() => { const shortcut = (event: KeyboardEvent) => { if (event.key === "Escape") { setMobileNav(false); } if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "k") { event.preventDefault(); setCommandOpen(v => !v); } }; window.addEventListener("keydown", shortcut); return () => window.removeEventListener("keydown", shortcut); }, []);
  const refresh = useCallback(async (id = currentSite.current) => { if (!id) return; const next = await api<SiteState>(`/api/sites/${id}/state`); if (currentSite.current === id) setState(next); return next; }, []);
  const refreshBootstrap = useCallback(async () => { const data = await api<Bootstrap>("/api/bootstrap"); setBootstrap(data); return data; }, []);
  useEffect(() => { if (initialLoad.current) return; initialLoad.current = true; (async () => { try { let data = await refreshBootstrap(); const search = new URLSearchParams(location.search); let selected: Site | undefined = data.sites.find(s => s.id === search.get("site")) || data.sites.find(s => s.id === localStorage.getItem("lumen-site")) || data.sites[0]; if (search.get("ga4") === "connected") flash("Google 계정이 연결됐어요. 분석할 속성을 선택해 주세요."); if (new URLSearchParams(location.search).get("demo") === "1") { selected = data.sites.find(s => s.mode === "demo"); if (!selected) { const created = await api<{ site: Site }>("/api/demo", "POST"); selected = created.site; data = await refreshBootstrap(); } history.replaceState({}, "", "/dashboard"); } if (selected) chooseSite(selected.id); else setLoading(false); if (search.get("start") === "1") { setEditItem(null); setForm("site"); search.delete("start"); history.replaceState({}, "", `${location.pathname}${search.size ? `?${search}` : ""}`); } if (search.get("ga4") === "error") setError("Google 연결을 완료하지 못했어요. 연결 상태를 확인하고 다시 시도해 주세요."); } catch (e) { setError((e as Error).message); setLoading(false); } })(); }, [refreshBootstrap, chooseSite, flash]);
  useEffect(() => { if (!siteId) return; let active = true; localStorage.setItem("lumen-site", siteId); api<SiteState>(`/api/sites/${siteId}/state`).then(data => { if (active) setState(data); }).catch(e => { if (active) setError(e.message); }).finally(() => { if (active) setLoading(false); }); return () => { active = false; }; }, [siteId]);
