  async function submitForm(values: Record<string, unknown>) { const root = `/api/sites/${siteId}`; if (form === "site") { setBusy(true); setError(""); try { const result = await api<{ site: Site }>(editItem ? root : "/api/sites", editItem ? "PATCH" : "POST", values); await refreshBootstrap(); if (editItem) await refresh(); else chooseSite(result.site.id); setForm(null); flash(editItem ? "브랜드 정보를 저장했어요" : "브랜드를 등록했어요. 이제 첫 질문을 추가해 보세요."); } catch (e) { setError((e as Error).message); throw e; } finally { setBusy(false); } return; }
    const addingPrompt = form === "prompt" && !editItem;
    const resource = form === "content" || form === "report" ? "documents" : `${form}s`; const result = await mutate(`${root}/${resource}${editItem ? `/${editItem.id}` : ""}`, editItem ? "PATCH" : "POST", form === "content" || form === "report" ? { ...values, kind: form } : values, form === "content" || form === "report" ? "문서를 생성했어요" : addingPrompt ? "질문을 추가했어요. 답변 수집 버튼을 눌러 다음 단계로 진행하세요." : "저장했어요"); if (addingPrompt) setPreferredPromptId((result as { prompt: Prompt }).prompt.id); setForm(null);
  }
  async function processRun(run: Run) { if (runLock.current) return; runLock.current = true; setRunning(true); setError(""); const targetSite = run.siteId; try { let current = run; while (["queued", "running"].includes(current.status)) { try { const response = await api<{ run: Run }>(`/api/sites/${targetSite}/runs/${run.id}/process`, "POST"); current = response.run; await refresh(targetSite); } catch (error) { if ((error as Error & { code?: string }).code !== "run_locked") throw error; await new Promise(resolve => setTimeout(resolve, 2500)); const response = await api<{ run: Run }>(`/api/sites/${targetSite}/runs/${run.id}`); current = response.run; await refresh(targetSite); } } flash(current.status === "completed" ? "답변 수집을 완료했어요" : "수집 결과를 확인해 주세요"); } catch (e) { setError((e as Error).message); } finally { runLock.current = false; setRunning(false); } }
